using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain the static queue to avoid cross-test pollution
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue after each test
        while (_service.ReceiveNotification() != null) { }
        _service.Dispose();
    }

    [Fact]
    public void SendNotification_CreatesNotificationWithCorrectFields()
    {
        // Act
        _service.SendNotification("Student", "42", EntityOperation.CREATE, "TestUser");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("TestUser", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.Contains("Student (ID: 42)", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesProperMessage()
    {
        // Act
        _service.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "TestUser");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student 'John Doe'", notification.Message);
        Assert.Contains("created", notification.Message);
    }

    [Fact]
    public void ReceiveNotification_DequeuesInOrder()
    {
        // Arrange
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        _service.SendNotification("Course", "2", EntityOperation.UPDATE);
        _service.SendNotification("Department", "3", EntityOperation.DELETE);

        // Act & Assert
        var first = _service.ReceiveNotification();
        Assert.Equal("Student", first!.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _service.ReceiveNotification();
        Assert.Equal("Course", second!.EntityType);
        Assert.Equal("2", second.EntityId);

        var third = _service.ReceiveNotification();
        Assert.Equal("Department", third!.EntityType);
        Assert.Equal("3", third.EntityId);
    }

    [Fact]
    public void ReceiveNotification_ReturnsNullWhenEmpty()
    {
        // Act
        var result = _service.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void SendNotification_QueueCapAt500Items()
    {
        // Arrange - enqueue 510 items
        for (int i = 0; i < 510; i++)
        {
            _service.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Act - count remaining items
        int count = 0;
        while (_service.ReceiveNotification() != null)
        {
            count++;
        }

        // Assert - should be capped at 500
        Assert.True(count <= 500, $"Queue should be capped at 500 but had {count} items");
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void GenerateMessage_ForEachEntityOperation_ContainsExpectedVerb(EntityOperation operation, string expectedVerb)
    {
        // Act
        _service.SendNotification("TestEntity", "1", "TestName", operation, "User");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
    }

    [Fact]
    public void GenerateMessage_Create_WithDisplayName_ReturnsCorrectFormat()
    {
        // Act
        _service.SendNotification("Course", "101", "Math 101", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.Equal("New Course 'Math 101' has been created", notification!.Message);
    }

    [Fact]
    public void GenerateMessage_Update_WithoutDisplayName_ReturnsCorrectFormat()
    {
        // Act
        _service.SendNotification("Course", "101", EntityOperation.UPDATE, "Admin");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.Equal("Course (ID: 101) has been updated", notification!.Message);
    }

    [Fact]
    public void GenerateMessage_Delete_WithDisplayName_ReturnsCorrectFormat()
    {
        // Act
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.Equal("Department 'Engineering' has been deleted", notification!.Message);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        // Act & Assert
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE, null);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.Equal("System", notification!.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        // Arrange
        var before = DateTime.Now.AddSeconds(-1);

        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var notification = _service.ReceiveNotification();
        var after = DateTime.Now.AddSeconds(1);
        Assert.InRange(notification!.CreatedAt, before, after);
    }
}

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_WithItems_ReturnsCorrectPage()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_SecondPage_ReturnsCorrectItems()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 2, 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 3, 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void HasPreviousPage_OnFirstPage_ReturnsFalse()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_OnSecondPage_ReturnsTrue()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 2, 10);

        // Assert
        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnFirstPage_ReturnsTrue()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 3, 10);

        // Assert
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_ExactDivision()
    {
        // Arrange
        var items = Enumerable.Range(1, 20).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.Equal(2, result.TotalPages);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_WithRemainder()
    {
        // Arrange
        var items = Enumerable.Range(1, 21).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void TotalPages_SingleItem_ReturnsOne()
    {
        // Arrange
        var items = new[] { 1 }.AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.Equal(1, result.TotalPages);
        Assert.Single(result);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        // Arrange
        var items = Enumerable.Empty<int>().AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(items, 1, 10);

        // Assert
        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }
}

