        var course = new Course { CourseID = 4001, Title = "With Image", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFormFile("photo.jpg", 1024);

        // Act
        var result = _controller.Create(course, mockFile);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var saved = _context.Courses.Find(4001);
        Assert.NotNull(saved);
        Assert.NotNull(saved.TeachingMaterialImagePath);
        Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
