            CourseID = 1001,
            Title = "Updated Chemistry",
            Credits = 4,
            DepartmentID = 1
        };
        // Detach original entity
        var existing = _context.Courses.Find(1001);
        _context.Entry(existing!).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        // Act
        var result = _controller.Edit(course, null!);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_POST_WithFileUpload_UpdatesImagePath()
    {
        // Arrange
        var course = new Course
        {
            CourseID = 1001,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1
        };
        var existing = _context.Courses.Find(1001);
        _context.Entry(existing!).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
        var mockFile = CreateMockFormFile("newimage.png", 2048);

        // Act
        var result = _controller.Edit(course, mockFile);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    // === DeleteConfirmed Tests ===

    [Fact]
    public void DeleteConfirmed_RemovesCourseAndRedirects()
    {
        // Arrange
        var initialCount = _context.Courses.Count();

        // Act
        var result = _controller.DeleteConfirmed(1001);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Courses.Count());
    }

    // === Helper Methods ===

    private static IFormFile CreateMockFormFile(string fileName, long size)
    {
        var content = new byte[size];
        var stream = new MemoryStream(content);
        var mock = new Mock<IFormFile>();
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(size);
        mock.Setup(f => f.OpenReadStream()).Returns(stream);
        mock.Setup(f => f.CopyTo(It.IsAny<Stream>()))
            .Callback<Stream>(s => stream.CopyTo(s));
        return mock.Object;
    }
}

