    private void SeedData()
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);

        var course1 = new Course { CourseID = 101, Title = "Calculus", Credits = 3, DepartmentID = 1 };
        var course2 = new Course { CourseID = 102, Title = "Algebra", Credits = 3, DepartmentID = 1 };
        _context.Courses.AddRange(course1, course2);

        var instructor1 = new Instructor
        {
            FirstMidName = "John",
            LastName = "Smith",
            HireDate = new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
        };
        var instructor2 = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            HireDate = new DateTime(2015, 6, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.AddRange(instructor1, instructor2);
        _context.SaveChanges();

        // Add course assignments after IDs are generated
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor1.ID,
            CourseID = 101
        });
        _context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor1.ID,
            CourseID = 102
        });

        // Add enrollment for course 101
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        _context.Enrollments.Add(new Enrollment
        {
            CourseID = 101,
            StudentID = student.ID,
            Grade = Grade.A
        });
        _context.SaveChanges();

        // Set department administrator
        dept.InstructorID = instructor1.ID;
        _context.SaveChanges();
    }

    // === Index Tests ===

    [Fact]
    public void Index_NoSelection_ReturnsAllInstructors()
    {
        // Act
        var result = _controller.Index(null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
