    {
        // Arrange
        var instructor = _context.Instructors.First(i => i.LastName == "Smith");

        // Act
        var result = _controller.Index(instructor.ID, 101) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments); // one enrollment in course 101
    }

