+using ContosoUniversity.Controllers;
+using ContosoUniversity.Data;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using ContosoUniversity.Tests.Helpers;
+using Microsoft.AspNetCore.Mvc;
+
+namespace ContosoUniversity.Tests.Controllers;
+
+public class NotificationsControllerTests : IDisposable
+{
+    private readonly SchoolContext _context;
+    private readonly NotificationsController _controller;
+    private readonly NotificationService _notificationService;
+
+    public NotificationsControllerTests()
+    {
+        _context = TestDbContextFactory.Create();
+        _notificationService = new NotificationService();
+        // Drain queue
+        while (_notificationService.ReceiveNotification() != null) { }
+        _controller = new NotificationsController(_context);
+    }
+
+    public void Dispose()
+    {
+        // Drain queue
+        while (_notificationService.ReceiveNotification() != null) { }
+        _controller.Dispose();
+        _context.Dispose();
+        _notificationService.Dispose();
+    }
+
+    [Fact]
+    public void GetNotifications_ReturnsNotificationsFromQueue()
+    {
+        // Arrange - enqueue some notifications via the shared static queue
+        _notificationService.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "User");
+        _notificationService.SendNotification("Course", "101", "Math", EntityOperation.UPDATE, "User");
+
+        // Act
+        var result = _controller.GetNotifications();
+
+        // Assert
+        Assert.NotNull(result);
+        var jsonResult = result as JsonResult;
+        Assert.NotNull(jsonResult);
+        // The result value is an anonymous type; verify it's not null and has data
+        Assert.NotNull(jsonResult.Value);
+        var value = jsonResult.Value!;
+        var successProp = value.GetType().GetProperty("success");
+        Assert.NotNull(successProp);
+        Assert.True((bool)successProp.GetValue(value)!);
+
+        var notificationsProp = value.GetType().GetProperty("notifications");
+        Assert.NotNull(notificationsProp);
+        var notifications = notificationsProp.GetValue(value) as List<Notification>;
+        Assert.NotNull(notifications);
+        Assert.True(notifications.Count >= 1); // may be affected by other tests' static queue usage
+    }
+
+    [Fact]
+    public void GetNotifications_ReturnsEmptyWhenNoNotifications()
+    {
+        // Act (queue should be drained in constructor)
+        var result = _controller.GetNotifications();
+
+        // Assert
+        var jsonResult = Assert.IsType<JsonResult>(result);
+        Assert.NotNull(jsonResult.Value);
+        var value = jsonResult.Value!;
+        var successProp = value.GetType().GetProperty("success");
+        Assert.True((bool)successProp!.GetValue(value)!);
+
+        var countProp = value.GetType().GetProperty("count");
+        Assert.Equal(0, (int)countProp!.GetValue(value)!);
+    }
+
+    [Fact]
+    public void GetNotifications_LimitsTo10()
+    {
+        // Arrange - enqueue 15 notifications
+        for (int i = 0; i < 15; i++)
+        {
+            _notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "User");
+        }
+
+        // Act
+        var result = _controller.GetNotifications() as JsonResult;
+
+        // Assert
+        Assert.NotNull(result);
+        var value = result.Value!;
+        var countProp = value.GetType().GetProperty("count");
+        var count = (int)countProp!.GetValue(value)!;
+        Assert.True(count <= 10);
+    }
+
+    [Fact]
+    public void MarkAsRead_ReturnsSuccessResponse()
+    {
+        // Act
+        var result = _controller.MarkAsRead(1);
+
+        // Assert
+        var jsonResult = Assert.IsType<JsonResult>(result);
+        Assert.NotNull(jsonResult.Value);
+        var value = jsonResult.Value!;
+        var successProp = value.GetType().GetProperty("success");
+        Assert.True((bool)successProp!.GetValue(value)!);
+    }
+}
