+using ContosoUniversity.Tests.Helpers;
+using Microsoft.AspNetCore.Mvc;
+
+namespace ContosoUniversity.Tests.Controllers;
+
+public class HomeControllerTests : IDisposable
+{
+    private readonly SchoolContext _context;
+    private readonly HomeController _controller;
+
+    public HomeControllerTests()
+    {
+        _context = TestDbContextFactory.Create();
+        SeedData();
+        _controller = new HomeController(_context);
+    }
+
+    public void Dispose()
+    {
+        _controller.Dispose();
+        _context.Dispose();
+    }
+
+    private void SeedData()
+    {
+        _context.Students.AddRange(
+            new Student { FirstMidName = "Alice", LastName = "A", EnrollmentDate = new DateTime(2023, 9, 1) },
+            new Student { FirstMidName = "Bob", LastName = "B", EnrollmentDate = new DateTime(2023, 9, 1) },
+            new Student { FirstMidName = "Charlie", LastName = "C", EnrollmentDate = new DateTime(2024, 1, 15) }
+        );
+        _context.SaveChanges();
+    }
+
+    [Fact]
+    public void Index_ReturnsViewResult()
+    {
+        // Act
+        var result = _controller.Index();
+
+        // Assert
+        Assert.IsType<ViewResult>(result);
+    }
+
+    [Fact]
+    public void About_ReturnsEnrollmentDateGroups()
+    {
+        // Act
+        var result = _controller.About() as ViewResult;
+
+        // Assert
+        Assert.NotNull(result);
+        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
+        Assert.Equal(2, model.Count); // Two distinct enrollment dates
+
+        var sept2023Group = model.FirstOrDefault(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
+        Assert.NotNull(sept2023Group);
+        Assert.Equal(2, sept2023Group.StudentCount);
+
+        var jan2024Group = model.FirstOrDefault(g => g.EnrollmentDate == new DateTime(2024, 1, 15));
+        Assert.NotNull(jan2024Group);
+        Assert.Equal(1, jan2024Group.StudentCount);
+    }
+
+    [Fact]
+    public void Contact_SetsViewBagMessage()
+    {
+        // Act
+        var result = _controller.Contact() as ViewResult;
+
+        // Assert
+        Assert.NotNull(result);
+        Assert.Equal("Your contact page.", _controller.ViewBag.Message);
+    }
+
+    [Fact]
+    public void Error_ReturnsViewResult()
+    {
+        // Act
+        var result = _controller.Error();
+
+        // Assert
+        Assert.IsType<ViewResult>(result);
+    }
+
+    [Fact]
+    public void Unauthorized_SetsViewBagMessageAndReturnsView()
+    {
+        // Act
+        var result = _controller.Unauthorized() as ViewResult;
+
+        // Assert
+        Assert.NotNull(result);
+        Assert.Equal("You don't have permission to access this resource.", (string)_controller.ViewBag.Message);
+    }
+}
